    private void RefreshPlanCatalogForTeam(TeamId team, TeamPlannerRuntimeState state)
    {
        if (state == null)
            return;

        EnsureSectorCatalogPlans(state);
        EnsureInvasionCatalogPlans(state, team);

        Dictionary<string, AIPlanIntent> activePlanByKey = new Dictionary<string, AIPlanIntent>();
        for (int i = 0; i < state.currentTurnPlans.Count; i++)
        {
            AIPlanIntent intent = state.currentTurnPlans[i];
            string key = AIPlanEvaluator.BuildPlanKey(intent);
            if (intent == null || string.IsNullOrWhiteSpace(key))
                continue;
            activePlanByKey[key] = intent;
        }

        Dictionary<ConstructionSector, SectorManager.SectorInfo> sectorInfoBySector = BuildSectorInfoMap();
        int currentTurn = matchController != null ? matchController.CurrentTurn : 0;

        foreach (PlannerCatalogPlanState planState in state.planCatalogByKey.Values)
        {
            if (planState == null)
                continue;

            PlannerCatalogStatus previousStatus = planState.status;
            planState.assignments.Clear();

            if (activePlanByKey.TryGetValue(planState.planKey, out AIPlanIntent activeIntent) && activeIntent != null)
            {
                planState.status = PlannerCatalogStatus.Active;
                planState.displayName = ResolveCatalogDisplayName(planState, activeIntent);
                planState.selectionReason = activeIntent.SelectionReason ?? string.Empty;
                planState.tacticalRiskScore = Mathf.Max(0, activeIntent.TacticalRiskScore);
                for (int a = 0; a < activeIntent.Assignments.Count; a++)
                {
                    AIPlanAssignment assignment = activeIntent.Assignments[a];
                    if (assignment != null)
                        planState.assignments.Add(assignment);
                }
            }
            else
            {
                planState.status = PlannerCatalogStatus.Inactive;
                planState.displayName = ResolveCatalogDisplayName(planState, null);
                planState.selectionReason = string.Empty;
                planState.tacticalRiskScore = 0;
            }

            if (!planState.isFixedPlan && sectorInfoBySector.TryGetValue(planState.sector, out SectorManager.SectorInfo sectorInfo) && sectorInfo != null)
            {
                int teamProgress = 0;
                IReadOnlyList<SectorManager.SectorConstructionInfo> constructions = sectorInfo.Constructions;
                for (int i = 0; i < constructions.Count; i++)
                {
                    SectorManager.SectorConstructionInfo construction = constructions[i];
                    if (construction == null)
                        continue;

                    int maxCapture = Mathf.Max(0, construction.CapturePointsMax);
                    int currentCapture = Mathf.Clamp(construction.CurrentCapturePoints, 0, maxCapture);
                    int contribution = construction.OwnerTeam == team
                        ? currentCapture
                        : Mathf.Max(0, maxCapture - currentCapture);

                    teamProgress += contribution;
                }

                planState.progressCurrent = teamProgress;
                planState.progressMax = Mathf.Max(0, sectorInfo.TotalCapturePointsMax);
                planState.conquered = sectorInfo.IsFullyControlled && sectorInfo.ControllingTeam == team;
                if (planState.conquered && planState.status != PlannerCatalogStatus.Active)
                    planState.status = PlannerCatalogStatus.Completed;
            }
            else if (planState.isFixedPlan)
            {
                planState.progressCurrent = 0;
                planState.progressMax = 0;
                planState.conquered = false;
            }
            else
            {
                planState.progressCurrent = 0;
                planState.progressMax = 0;
                planState.conquered = false;
            }

            if (planState.status == PlannerCatalogStatus.Active && previousStatus != PlannerCatalogStatus.Active)
                planState.lastActivationTurn = currentTurn;
            if (planState.status == PlannerCatalogStatus.Completed && previousStatus != PlannerCatalogStatus.Completed)
                planState.lastCompletionTurn = currentTurn;
        }
    }

    private void EnsureSectorCatalogPlans(TeamPlannerRuntimeState state)
    {
        IReadOnlyList<SectorManager.SectorInfo> sectors = SectorManager.GetAllSectorInfos();
        for (int i = 0; i < sectors.Count; i++)
        {
            SectorManager.SectorInfo sectorInfo = sectors[i];
            if (sectorInfo == null)
                continue;

            string key = BuildSectorCatalogPlanKey(sectorInfo.Sector);
            EnsureCatalogPlan(state, key, sectorInfo.Sector.ToString(), sectorInfo.Sector, false, string.Empty);
        }
    }

    private void EnsureInvasionCatalogPlans(TeamPlannerRuntimeState state, TeamId aiTeam)
    {
        IReadOnlyList<SectorManager.SectorInfo> bases = SectorManager.GetAllBaseInfos();
        for (int i = 0; i < bases.Count; i++)
        {
            SectorManager.SectorInfo baseInfo = bases[i];
            if (baseInfo == null)
                continue;

            // Ignora a propria base da IA.
            if (baseInfo.ControllingTeam == aiTeam)
                continue;

            string key = BuildInvasionPlanKey(baseInfo.Sector);
            string displayName = $"InvasÃƒÂ£o {baseInfo.Sector}";
            EnsureCatalogPlan(state, key, displayName, baseInfo.Sector, false, string.Empty);
        }
    }

    private static string BuildInvasionPlanKey(ConstructionSector sector)
    {
        return $"invasion:{sector}";
    }

    private static void EnsureCatalogPlan(TeamPlannerRuntimeState state, string key, string displayName, ConstructionSector sector, bool isFixedPlan, string fixedPlanKind)
    {
        if (state == null || string.IsNullOrWhiteSpace(key))
            return;

        if (!state.planCatalogByKey.TryGetValue(key, out PlannerCatalogPlanState planState) || planState == null)
        {
            planState = new PlannerCatalogPlanState { planKey = key };
            state.planCatalogByKey[key] = planState;
        }

        planState.displayName = displayName ?? string.Empty;
        planState.sector = sector;
        planState.isFixedPlan = isFixedPlan;
        planState.fixedPlanKind = fixedPlanKind ?? string.Empty;
    }

    private static Dictionary<ConstructionSector, SectorManager.SectorInfo> BuildSectorInfoMap()
    {
        Dictionary<ConstructionSector, SectorManager.SectorInfo> result = new Dictionary<ConstructionSector, SectorManager.SectorInfo>();
        IReadOnlyList<SectorManager.SectorInfo> sectors = SectorManager.GetAllSectorInfos();
        for (int i = 0; i < sectors.Count; i++)
        {
            SectorManager.SectorInfo sectorInfo = sectors[i];
            if (sectorInfo != null)
                result[sectorInfo.Sector] = sectorInfo;
        }

        return result;
    }

    private static int CompareCatalogPlansForDebug(PlannerCatalogPlanState a, PlannerCatalogPlanState b)
    {
        int statusCompare = CompareStatusForDebug(a != null ? a.status : PlannerCatalogStatus.Inactive, b != null ? b.status : PlannerCatalogStatus.Inactive);
        if (statusCompare != 0)
            return statusCompare;

        int fixedCompare = (a != null && a.isFixedPlan ? 0 : 1).CompareTo(b != null && b.isFixedPlan ? 0 : 1);
        if (fixedCompare != 0)
            return fixedCompare;

        return string.CompareOrdinal(a != null ? a.planKey : string.Empty, b != null ? b.planKey : string.Empty);
    }

    private static int CompareStatusForDebug(PlannerCatalogStatus a, PlannerCatalogStatus b)
    {
        int rankA = a == PlannerCatalogStatus.Active ? 0
            : a == PlannerCatalogStatus.Inactive ? 1
            : a == PlannerCatalogStatus.Completed ? 2
            : 3;
        int rankB = b == PlannerCatalogStatus.Active ? 0
            : b == PlannerCatalogStatus.Inactive ? 1
            : b == PlannerCatalogStatus.Completed ? 2
            : 3;
        return rankA.CompareTo(rankB);
    }

    private string ResolveCatalogDisplayName(PlannerCatalogPlanState planState, AIPlanIntent activeIntent)
    {
        if (planState == null)
            return string.Empty;
        if (!string.IsNullOrWhiteSpace(planState.displayName))
            return planState.displayName;
        if (activeIntent != null)
            return ResolvePlanDisplayName(activeIntent);
        return planState.sector.ToString();
    }

    private static string BuildSectorCatalogPlanKey(ConstructionSector sector)
    {
        return $"dynamic:capture:{sector}";
    }

    private List<TeamId> GetPlannerDebugTeams()
    {
        EnsureAIDataDefaults();

        List<TeamId> teams = new List<TeamId>();
        if (matchController != null)
        {
            IReadOnlyList<TeamId> players = matchController.Players;
            if (players != null)
            {
                for (int i = 0; i < players.Count; i++)
                {
                    TeamId team = players[i];
                    if (!matchController.IsPlayerAI(team))
                        continue;

                    GetOrCreatePlannerState(team);
                    teams.Add(team);
                }
            }
        }

        if (teams.Count == 0)
            teams.AddRange(plannerStateByTeam.Keys);

        teams.Sort((a, b) => ((int)a).CompareTo((int)b));
        return teams;
    }

    public void RefreshPlannerDebugViewNow()
    {
        plannerDebugView.Clear();

        List<TeamId> teams = GetPlannerDebugTeams();

        for (int t = 0; t < teams.Count; t++)
        {
            TeamId team = teams[t];
            TeamPlannerRuntimeState state = plannerStateByTeam[team];
            TeamPlannerDebugView teamView = new TeamPlannerDebugView
            {
                team = team,
                currentStanceName = state.currentStance.ToString()
            };

            RefreshPlanCatalogForTeam(team, state);

            List<PlannerCatalogPlanState> catalogPlans = new List<PlannerCatalogPlanState>(state.planCatalogByKey.Values);
            catalogPlans.Sort(CompareCatalogPlansForDebug);

            for (int i = 0; i < catalogPlans.Count; i++)
            {
                PlannerCatalogPlanState planState = catalogPlans[i];
                if (planState == null)
                    continue;

                PlanDebugView planView = new PlanDebugView
                {
                    planKey = planState.planKey,
                    displayName = planState.displayName,
                    sector = planState.sector.ToString(),
                    status = planState.status.ToString(),
                    conquered = planState.conquered,
                    progressCurrent = planState.progressCurrent,
                    progressMax = planState.progressMax,
                    lastActivationTurn = planState.lastActivationTurn,
                    lastCompletionTurn = planState.lastCompletionTurn,
                    tacticalRiskScore = planState.tacticalRiskScore,
                    selectionReason = planState.selectionReason
                };

                List<AIPlanAssignment> assignments = new List<AIPlanAssignment>(planState.assignments);
                assignments.Sort((a, b) => a.UnitInstanceId.CompareTo(b.UnitInstanceId));
                for (int a = 0; a < assignments.Count; a++)
                {
                    AIPlanAssignment assignment = assignments[a];
                    if (assignment == null)
                        continue;

                    UnitManager unit = FindUnitById(assignment.UnitInstanceId);
                    planView.assignments.Add(new AssignmentDebugView
                    {
                        unitInstanceId = assignment.UnitInstanceId,
                        unitName = unit != null ? unit.name : string.Empty,
                        role = assignment.Role.ToDebugLabel()
                    });
                }

                teamView.plans.Add(planView);
            }

            foreach (var kv in state.unitAssignments)
            {
                AIPlanAssignment assignment = kv.Value;
                if (assignment == null)
                    continue;
                if (assignment.Intent != null && !state.currentTurnPlans.Contains(assignment.Intent))
                    Debug.LogWarning($"[AI][planner-debug] Inconsistencia: time {team} possui assignment {assignment.UnitInstanceId} para plano ausente no state.");
            }

            plannerDebugView.Add(teamView);
        }

        plannerDebugViewDirty = false;
    }

    private void RefreshPlannerDebugViewIfDirty()
    {
        if (!plannerDebugViewDirty)
            return;

        RefreshPlannerDebugViewNow();
    }


    public void RemoveTeamState(TeamId team)
    {
        if (!plannerStateByTeam.Remove(team))
            return;

        MarkPlannerDebugViewDirty();
        RefreshPlannerDebugViewIfDirty();
        Debug.Log($"[AI][planner] estado removido para time {team}.");
    }

    private void HandleTeamDefeated(TeamId team)
    {
        RemoveTeamState(team);
    }

    private void HandleUnitDestroyedPlannerCleanup(UnitManager unit)
    {
        if (unit == null)
            return;

        int unitId = unit.InstanceId;
        bool changed = false;

        foreach (var stateKvp in plannerStateByTeam)
        {
            TeamPlannerRuntimeState state = stateKvp.Value;
            if (state == null)
                continue;

            if (state.unitRoles.Remove(unitId))
                changed = true;
            if (state.unitAssignments.Remove(unitId))
                changed = true;
            if (state.previousAssignmentsByUnitId.Remove(unitId))
                changed = true;

            for (int i = 0; i < state.currentTurnPlans.Count; i++)
            {
                AIPlanIntent intent = state.currentTurnPlans[i];
                if (intent == null || intent.Assignments == null)
                    continue;

                int removed = intent.Assignments.RemoveAll(a => a != null && a.UnitInstanceId == unitId);
                if (removed > 0)
                    changed = true;
            }
        }

        if (!changed)
            return;

        MarkPlannerDebugViewDirty();
        RefreshPlannerDebugViewIfDirty();
    }
    public AIPlannerMultiTeamSaveData BuildPlannerSaveData()
    {
        AIPlannerMultiTeamSaveData data = new AIPlannerMultiTeamSaveData();
        List<TeamId> teams = new List<TeamId>(plannerStateByTeam.Keys);
        teams.Sort((a, b) => ((int)a).CompareTo((int)b));

        for (int t = 0; t < teams.Count; t++)
        {
            TeamId team = teams[t];
            if (matchController != null && !matchController.IsPlayerAI(team))
                continue;

            TeamPlannerRuntimeState state = plannerStateByTeam[team];
            TeamPlannerSaveBlock teamBlock = new TeamPlannerSaveBlock
            {
                teamId = (int)team,
                hasRestoredStatePendingUse = state.hasRestoredStatePendingUse,
                restoredTurn = state.restoredTurn
            };

            RefreshPlanCatalogForTeam(team, state);
            foreach (var catalogKvp in state.planCatalogByKey)
            {
                SavedCatalogPlan savedCatalog = BuildSavedCatalogPlan(catalogKvp.Value);
                if (savedCatalog != null)
                    teamBlock.catalogPlans.Add(savedCatalog);
            }

            for (int i = 0; i < state.currentTurnPlans.Count; i++)
            {
                AIPlanIntent intent = state.currentTurnPlans[i];
                if (intent == null)
                    continue;

                string planKey = AIPlanEvaluator.BuildPlanKey(intent);
                if (string.IsNullOrWhiteSpace(planKey))
                    continue;

                teamBlock.activePlans.Add(new SavedPlan
                {
                    planKey = planKey,
                    displayName = ResolvePlanDisplayName(intent),
                    sector = intent.Sector.ToString(),
                    badgeSymbol = intent.BadgeSymbol,
                    tacticalRiskScore = intent.TacticalRiskScore,
                    selectionReason = intent.SelectionReason,
                    hasCaptureTarget = intent.HasCaptureTarget,
                    captureX = intent.CaptureTargetCell.x,
                    captureY = intent.CaptureTargetCell.y,
                    captureLabel = intent.CaptureTargetLabel
                });
            }

            foreach (var kv in state.unitAssignments)
            {
                AIPlanAssignment assignment = kv.Value;
                if (assignment == null || assignment.Intent == null)
                    continue;

                string planKey = AIPlanEvaluator.BuildPlanKey(assignment.Intent);
                if (string.IsNullOrWhiteSpace(planKey))
                    continue;

                teamBlock.assignments.Add(new SavedAssignment
                {
                    unitInstanceId = assignment.UnitInstanceId,
                    planKey = planKey,
                    role = (int)assignment.Role,
                    roleName = assignment.Role.ToString()
                });
            }

            foreach (var kv in state.previousAssignmentsByUnitId)
            {
                AIPlanEvaluator.MissionAssignmentMemory memory = kv.Value;
                if (string.IsNullOrWhiteSpace(memory.PlanKey))
                    continue;

                teamBlock.previousAssignments.Add(new SavedPreviousAssignmentMemory
                {
                    unitInstanceId = memory.UnitInstanceId,
                    planKey = memory.PlanKey,
                    role = (int)memory.Role,
                    roleName = memory.Role.ToString(),
                    lastProgressTurn = memory.LastProgressTurn,
                    lastDistanceToTarget = memory.LastDistanceToTarget
                });
            }

            data.teams.Add(teamBlock);
        }

        return data;
    }

    public void RestorePlannerSaveData(AIPlannerMultiTeamSaveData data)
    {
        plannerStateByTeam.Clear();

        if (data == null || data.teams == null || data.teams.Count == 0)
        {
            plannerDebugView.Clear();
            plannerDebugViewDirty = false;
            return;
        }

        int restoredAssignments = 0;
        int droppedAssignments = 0;
        int activeTeamIdAtLoad = matchController != null ? matchController.ActiveTeamId : int.MinValue;

        for (int i = 0; i < data.teams.Count; i++)
        {
            TeamPlannerSaveBlock teamBlock = data.teams[i];
            if (teamBlock == null)
                continue;
            if (!System.Enum.IsDefined(typeof(TeamId), teamBlock.teamId))
                continue;

            TeamId team = (TeamId)teamBlock.teamId;
            if (matchController != null && !matchController.IsPlayerAI(team))
                continue;

            TeamPlannerRuntimeState state = GetOrCreatePlannerState(team);
            state.currentTurnPlans.Clear();
            state.unitRoles.Clear();
            state.unitAssignments.Clear();
            state.previousAssignmentsByUnitId.Clear();
            state.currentPlannerLifecycleLogs.Clear();
            state.previousPlanMetricsByKey.Clear();
            state.planCatalogByKey.Clear();
            state.restoredTurn = teamBlock.restoredTurn >= 0 ? teamBlock.restoredTurn : (matchController != null ? matchController.CurrentTurn : 0);

            EnsureSectorCatalogPlans(state);
            EnsureInvasionCatalogPlans(state, team);
            if (teamBlock.catalogPlans != null)
            {
                for (int c = 0; c < teamBlock.catalogPlans.Count; c++)
                    TryApplySavedCatalogPlan(state, teamBlock.catalogPlans[c]);
            }

            Dictionary<string, AIPlanIntent> planByKey = new Dictionary<string, AIPlanIntent>(System.StringComparer.Ordinal);
            if (teamBlock.activePlans != null)
            {
                for (int p = 0; p < teamBlock.activePlans.Count; p++)
                {
                    SavedPlan savedPlan = teamBlock.activePlans[p];
                    if (savedPlan == null || string.IsNullOrWhiteSpace(savedPlan.planKey))
                        continue;

                    if (TryBuildIntentFromSavedPlan(savedPlan, out AIPlanIntent intent))
                    {
                        state.currentTurnPlans.Add(intent);
                        planByKey[savedPlan.planKey] = intent;
                    }
                    else
                    {
                        Debug.LogWarning($"[AI][planner-load][{team}] plano nao restaurado: {savedPlan.planKey}");
                    }
                }
            }

            if (teamBlock.assignments != null)
            {
                for (int a = 0; a < teamBlock.assignments.Count; a++)
                {
                    SavedAssignment saved = teamBlock.assignments[a];
                    if (saved == null || saved.unitInstanceId <= 0 || string.IsNullOrWhiteSpace(saved.planKey))
                        continue;

                    if (!planByKey.TryGetValue(saved.planKey, out AIPlanIntent intent) || intent == null)
                    {
                        droppedAssignments++;
                        Debug.LogWarning($"[AI][planner-load][{team}] assignment descartado (plano ausente): unit={saved.unitInstanceId} plan={saved.planKey}");
                        continue;
                    }

                    UnitManager unit = FindUnitById(saved.unitInstanceId);
                    if (unit == null || unit.IsDead || unit.TeamId != team)
                    {
                        droppedAssignments++;
                        Debug.LogWarning($"[AI][planner-load][{team}] assignment descartado (unidade invalida): unit={saved.unitInstanceId} plan={saved.planKey}");
                        continue;
                    }

                    AIPlanRole role = TryParseSavedRole(saved.role, saved.roleName);
                    AIPlanAssignment assignment = new AIPlanAssignment
                    {
                        UnitInstanceId = unit.InstanceId,
                        Role = role,
                        Intent = intent
                    };

                    if (role == AIPlanRole.Capture && intent.HasCaptureTarget)
                    {
                        assignment.HasPlannedCaptureTarget = true;
                        assignment.PlannedCaptureCell = intent.CaptureTargetCell;
                        assignment.PlannedCaptureLabel = intent.CaptureTargetLabel;
                    }

                    intent.Assignments.Add(assignment);
                    state.unitAssignments[unit.InstanceId] = assignment;
                    state.unitRoles[unit.InstanceId] = intent;
                    restoredAssignments++;
                }
            }

            if (teamBlock.previousAssignments != null)
            {
                for (int m = 0; m < teamBlock.previousAssignments.Count; m++)
                {
                    SavedPreviousAssignmentMemory savedMemory = teamBlock.previousAssignments[m];
                    if (savedMemory == null || savedMemory.unitInstanceId <= 0 || string.IsNullOrWhiteSpace(savedMemory.planKey))
                        continue;

                    AIPlanRole role = TryParseSavedRole(savedMemory.role, savedMemory.roleName);
                    state.previousAssignmentsByUnitId[savedMemory.unitInstanceId] = new AIPlanEvaluator.MissionAssignmentMemory
                    {
                        UnitInstanceId = savedMemory.unitInstanceId,
                        PlanKey = savedMemory.planKey,
                        Role = role,
                        LastProgressTurn = savedMemory.lastProgressTurn,
                        LastDistanceToTarget = savedMemory.lastDistanceToTarget
                    };
                }
            }

            state.hasRestoredStatePendingUse = teamBlock.hasRestoredStatePendingUse
                && state.currentTurnPlans.Count > 0
                && (int)team == activeTeamIdAtLoad;
            if (!teamBlock.hasRestoredStatePendingUse && state.currentTurnPlans.Count > 0)
                state.hasRestoredStatePendingUse = state.currentTurnPlans.Count > 0 && (int)team == activeTeamIdAtLoad;
            if (state.restoredTurn < 0 && matchController != null)
                state.restoredTurn = matchController.CurrentTurn;

            ApplyUnitPlanDebugBadges(team);
            if (state.currentTurnPlans.Count > 0 && !state.hasRestoredStatePendingUse)
            {
                Debug.Log($"[AI][planner-load][{team}] restore aguardando turno futuro; activeTeamAtLoad={(TeamId)activeTeamIdAtLoad} consumeOnNextEvaluate={state.hasRestoredStatePendingUse}");
            }
            Debug.Log($"[AI][planner-load][{team}] planos={state.currentTurnPlans.Count} assignments={state.unitAssignments.Count} previous={state.previousAssignmentsByUnitId.Count} pendingUse={state.hasRestoredStatePendingUse}");
        }

        MarkPlannerDebugViewDirty();
        RefreshPlannerDebugViewIfDirty();
        Debug.Log($"[AI][planner-load] assignments restaurados={restoredAssignments} descartados={droppedAssignments}");
    }

    private bool TryBuildIntentFromSavedPlan(SavedPlan savedPlan, out AIPlanIntent intent)
    {
        intent = null;
        if (savedPlan == null || string.IsNullOrWhiteSpace(savedPlan.planKey))
            return false;

        if (TryParseDynamicCapturePlanKey(savedPlan.planKey, out ConstructionSector dynamicSector))
        {
            intent = new AIPlanIntent
            {
                Sector = dynamicSector,
                DisplayName = !string.IsNullOrWhiteSpace(savedPlan.displayName) ? savedPlan.displayName : $"Captura {dynamicSector}",
                BadgeSymbol = !string.IsNullOrWhiteSpace(savedPlan.badgeSymbol) ? savedPlan.badgeSymbol : GetSectorBadgeSymbol(dynamicSector),
                TacticalRiskScore = Mathf.Max(0, savedPlan.tacticalRiskScore),
                SelectionReason = savedPlan.selectionReason
            };
        }
        else if (System.Enum.TryParse(savedPlan.sector, true, out ConstructionSector sectorFromSave))
        {
            intent = new AIPlanIntent
            {
                Sector = sectorFromSave,
                DisplayName = !string.IsNullOrWhiteSpace(savedPlan.displayName) ? savedPlan.displayName : sectorFromSave.ToString(),
                BadgeSymbol = !string.IsNullOrWhiteSpace(savedPlan.badgeSymbol) ? savedPlan.badgeSymbol : GetSectorBadgeSymbol(sectorFromSave),
                TacticalRiskScore = Mathf.Max(0, savedPlan.tacticalRiskScore),
                SelectionReason = savedPlan.selectionReason
            };
        }

        if (intent == null)
            return false;

        intent.HasCaptureTarget = savedPlan.hasCaptureTarget;
        intent.CaptureTargetCell = new Vector3Int(savedPlan.captureX, savedPlan.captureY, 0);
        intent.CaptureTargetLabel = savedPlan.captureLabel;
        return true;
    }

    private static AIPlanRole TryParseSavedRole(int roleValue, string roleName)
    {
        if (System.Enum.IsDefined(typeof(AIPlanRole), roleValue))
            return (AIPlanRole)roleValue;

        if (!string.IsNullOrWhiteSpace(roleName) && System.Enum.TryParse(roleName, true, out AIPlanRole parsed))
            return parsed;

        return AIPlanRole.Assault;
    }

    private void Awake()
    {
        EnsureAIDataDefaults();
        fallbackBehaviorProfile = ScriptableObject.CreateInstance<BeginnerAIProfile>();
    }

    private void OnEnable()
    {
        MatchController.OnActiveTeamChanged += HandleActiveTeamChanged;
        MatchController.OnSlotConfigChanged += HandleSlotConfigChanged;
        MatchController.OnTeamDefeated += HandleTeamDefeated;
        TurnStateManager.OnUnitDestroyed += HandleUnitDestroyedPlannerCleanup;
        SaveGameManager.OnAfterLoadSuccess += HandleAfterLoadSuccess;
    }

#if UNITY_EDITOR
    private void OnValidate()
    {
        EnsureAIDataDefaults();
    }
#endif

    private void EnsureAIDataDefaults()
    {
        RefreshAiTeamProfileAssignments();

        for (int i = 0; i < teamProfileAssignments.Count; i++)
        {
            AIGeneralProfile p = teamProfileAssignments[i].profile;
            if (p != null && p.aiData != null)
                p.aiData.EnsureDefaults();
        }
    }

    private void HandleSlotConfigChanged()
    {
        RefreshAiTeamProfileAssignments();
    }

    private void RefreshAiTeamProfileAssignments()
    {
        if (matchController == null)
            matchController = FindAnyObjectByType<MatchController>();

        teamProfileAssignments.Clear();

        if (matchController == null || aiDatabase == null || aiDatabase.profiles == null)
            return;

        HashSet<AIGeneralProfile> used = new HashSet<AIGeneralProfile>();
        IReadOnlyList<TeamId> players = matchController.Players;
        if (players == null)
            return;

        for (int i = 0; i < players.Count; i++)
        {
            TeamId team = players[i];
            if (!matchController.IsPlayerAI(team))
                continue;

            AIGeneralProfile resolved = SelectBestProfileForTeam(team, used);
            TeamProfileAssignment assignment = new TeamProfileAssignment
            {
                team = team,
                profile = resolved
            };
            teamProfileAssignments.Add(assignment);

            if (resolved != null)
                used.Add(resolved);
        }
    }

    private AIGeneralProfile SelectBestProfileForTeam(TeamId team, HashSet<AIGeneralProfile> used)
    {
        if (aiDatabase == null || aiDatabase.profiles == null)
            return null;

        for (int i = 0; i < aiDatabase.profiles.Count; i++)
        {
            AIGeneralProfile p = aiDatabase.profiles[i];
            if (p == null || p.aiData == null)
                continue;
            if (p.preferedTeamAssignment != team)
                continue;
            if (used.Contains(p))
                continue;
            return p;
        }

        for (int i = 0; i < aiDatabase.profiles.Count; i++)
        {
            AIGeneralProfile p = aiDatabase.profiles[i];
            if (p == null || p.aiData == null)
                continue;
            if (p.preferedTeamAssignment != TeamId.Neutral)
                continue;
            if (used.Contains(p))
                continue;
            return p;
        }

        for (int i = 0; i < aiDatabase.profiles.Count; i++)
        {
            AIGeneralProfile p = aiDatabase.profiles[i];
            if (p == null || p.aiData == null)
                continue;
            if (p.preferedTeamAssignment == team)
                return p;
        }

        for (int i = 0; i < aiDatabase.profiles.Count; i++)
        {
            AIGeneralProfile p = aiDatabase.profiles[i];
            if (p == null || p.aiData == null)
                continue;
            if (p.preferedTeamAssignment == TeamId.Neutral)
                return p;
        }

        return null;
    }

    private AIGeneralProfile GetAssignedProfileForTeam(TeamId team)
    {
        for (int i = 0; i < teamProfileAssignments.Count; i++)
        {
            TeamProfileAssignment a = teamProfileAssignments[i];
            if (a.team == team)
                return a.profile;
        }
        return null;
    }

    private AIProfile GetBehaviorProfile(TeamId team)
    {
        AIGeneralProfile general = GetAssignedProfileForTeam(team);
        if (general != null && general.behaviorProfile != null)
            return general.behaviorProfile;
        return fallbackBehaviorProfile;
    }

    public bool TryGetAssignedAIDataForTeam(TeamId team, out AIData data, out AIGeneralProfile profileForTeam)
    {
        RefreshAiTeamProfileAssignments();
        profileForTeam = GetAssignedProfileForTeam(team);
        data = profileForTeam != null ? profileForTeam.aiData : null;
        return data != null;
    }

    private AIData GetEffectiveAIData(TeamId aiTeam)
    {
        RefreshAiTeamProfileAssignments();

        AIGeneralProfile assigned = GetAssignedProfileForTeam(aiTeam);
        if (assigned != null && aiDatabase != null)
        {
            AIData fromDb = aiDatabase.ResolveFor(currentStance, assigned);
            if (fromDb != null)
            {
                fromDb.EnsureDefaults();
                return fromDb;
            }
        }

        if (assigned != null && assigned.aiData != null)
        {
            assigned.aiData.EnsureDefaults();
            return assigned.aiData;
        }

        if (runtimeAiDataFallback == null)
            runtimeAiDataFallback = AIData.CreateRuntimeBasic();
        else
            runtimeAiDataFallback.EnsureDefaults();

        return runtimeAiDataFallback;
    }
    private void OnDisable()
    {
        MatchController.OnActiveTeamChanged -= HandleActiveTeamChanged;
        MatchController.OnSlotConfigChanged -= HandleSlotConfigChanged;
        MatchController.OnTeamDefeated -= HandleTeamDefeated;
        TurnStateManager.OnUnitDestroyed -= HandleUnitDestroyedPlannerCleanup;
        SaveGameManager.OnAfterLoadSuccess -= HandleAfterLoadSuccess;
        if (activeTurnRoutine != null)
            StopCoroutine(activeTurnRoutine);
    }

    private void HandleAfterLoadSuccess()
    {
        if (!Application.isPlaying || !debugRunPostLoadPlannerRebuildTest)
            return;

        StartCoroutine(DebugRunPostLoadPlannerRebuildTestNextFrame());
    }

    private IEnumerator DebugRunPostLoadPlannerRebuildTestNextFrame()
    {
        yield return null;
        DebugForceRebuildSnapshotAndReevaluate(debugPostLoadPlannerTeam);
    }
    private void HandleActiveTeamChanged(int teamId)
    {
        if (matchController == null)
            matchController = FindAnyObjectByType<MatchController>();
        if (turnStateManager == null)
            turnStateManager = FindAnyObjectByType<TurnStateManager>();

        if (activeTurnRoutine != null)
        {
            StopCoroutine(activeTurnRoutine);
            activeTurnRoutine = null;
        }

        if (matchController == null)
            return;

        if (!matchController.IsActiveTeamAI())
            return;

        if (SaveGameManager.IsAnyLoadInProgress)
        {
            if (aiLog)
                Debug.Log($"[AI] HandleActiveTeamChanged ignorado durante load (teamId={teamId}).");
            return;
        }

        TeamId aiTeam = (TeamId)teamId;

        activeTurnRoutine = StartCoroutine(ExecuteAITurn(aiTeam));
    }

