    private static bool IsSupplyTruckOutOfReserves(UnitManager unit, AIUnitProfile profile = null)
    {
        if (unit == null)
            return false;

        IReadOnlyList<UnitEmbarkedSupply> resources = unit.GetEmbarkedResources();
        if (resources == null || resources.Count <= 0)
            return true;

        List<UnitEmbarkedSupply> baseline = null;
        if (unit.TryGetUnitData(out UnitData unitDataRef) && unitDataRef != null)
            baseline = unitDataRef.supplierResources;

        int fuelThreshold  = profile != null ? profile.restockFuelThresholdPercent  : 0;
        int ammoThreshold  = profile != null ? profile.restockAmmoThresholdPercent  : 0;
        int partsThreshold = profile != null ? profile.restockPartsThresholdPercent : 0;

        bool hasCore = false;
        for (int i = 0; i < resources.Count; i++)
        {
            UnitEmbarkedSupply entry = resources[i];
            if (entry == null || entry.supply == null)
                continue;
            if (!IsCoreSupplyForTruck(entry.supply))
                continue;

            hasCore = true;

            if (entry.amount <= 0)
                return true;

            int threshold = GetRestockThresholdForSupply(entry.supply, fuelThreshold, ammoThreshold, partsThreshold);
            if (threshold > 0)
            {
                int maxAmount = FindBaselineSupplyAmount(baseline, entry.supply);
                if (maxAmount > 0 && entry.amount * 100 < maxAmount * threshold)
                    return true;
            }
        }

        if (hasCore)
            return false;

        // Fallback: sem mapeamento de supply core, considera vazio apenas quando TODOS estao zerados.
        bool hasAnyPositive = false;
        for (int i = 0; i < resources.Count; i++)
        {
            UnitEmbarkedSupply entry = resources[i];
            if (entry != null && entry.amount > 0)
            {
                hasAnyPositive = true;
                break;
            }
        }

        return !hasAnyPositive;
    }

    private static int GetRestockThresholdForSupply(SupplyData supply, int fuelThreshold, int ammoThreshold, int partsThreshold)
    {
        string text = ((supply.id ?? "") + " " + (supply.displayName ?? "")).ToLowerInvariant();
        if (text.Contains("galao")) return fuelThreshold;
        if (text.Contains("caixa")) return ammoThreshold;
        if (text.Contains("peca"))  return partsThreshold;
        return 0;
    }

    private static int FindBaselineSupplyAmount(List<UnitEmbarkedSupply> baseline, SupplyData supply)
    {
        if (baseline == null || supply == null)
            return 0;
        for (int i = 0; i < baseline.Count; i++)
        {
            if (baseline[i] != null && baseline[i].supply == supply)
                return baseline[i].amount;
        }
        return 0;
    }

    private static bool IsCoreSupplyForTruck(SupplyData supply)
    {
        if (supply == null)
            return false;

        string id = !string.IsNullOrWhiteSpace(supply.id) ? supply.id : string.Empty;
        string name = !string.IsNullOrWhiteSpace(supply.displayName) ? supply.displayName : string.Empty;
        string text = (id + " " + name).ToLowerInvariant();

        return text.Contains("peca")
            || text.Contains("galao")
            || text.Contains("caixa");
    }

    private bool TryGetMostCriticalAllyForSupply(UnitManager supplier, AISnapshot snapshot, out UnitManager target)
    {
        target = null;
        if (supplier == null || snapshot == null)
            return false;

        AIUnitProfile supplierProfile = null;
        if (supplier.TryGetUnitData(out UnitData supplierDataNav) && supplierDataNav != null)
            supplierProfile = supplierDataNav.aiUnitProfile;

        Vector3Int supplierCell = supplier.CurrentCellPosition;
        supplierCell.z = 0;

        // Prioridade 1: alvos validados pelo sensor (adjacentes/alcance valido agora).
        // Entre eles, escolhe o mais proximo; criticidade desempata.
        if (turnStateManager != null)
        {
            var sensorOptions = new List<PodeSuprirOption>();
            if (turnStateManager.TryGetSupplyTargets(supplier, sensorOptions, out _) && sensorOptions.Count > 0)
            {
                int bestDistance = int.MaxValue;
                int bestScore = int.MinValue;
                for (int i = 0; i < sensorOptions.Count; i++)
                {
                    UnitManager candidate = sensorOptions[i]?.targetUnit;
                    if (candidate == null || candidate.IsDead)
                        continue;
                    if (!IsSupplyTruckTargetThresholdMet(candidate, out int score, supplierProfile))
                        continue;

                    Vector3Int candidateCell = candidate.CurrentCellPosition;
                    candidateCell.z = 0;
                    int distance = GetHexDistance(snapshot.BoardTilemap, supplierCell, candidateCell, 64);
                    if (distance == int.MaxValue)
                        distance = 64;

                    bool better = distance < bestDistance || (distance == bestDistance && score > bestScore);
                    if (!better)
                        continue;

                    bestDistance = distance;
                    bestScore = score;
                    target = candidate;
                }
                if (target != null)
                    return true;
            }
        }

        // Prioridade 2: objetivo de navegacao ? aliado mais proximo no snapshot.
        // Criticidade entra apenas como desempate.
        if (snapshot.FriendlyUnits == null)
            return false;

        int navBestDistance = int.MaxValue;
        int navBestScore = int.MinValue;

        for (int i = 0; i < snapshot.FriendlyUnits.Count; i++)
        {
            UnitManager ally = snapshot.FriendlyUnits[i];
            if (ally == null || ally == supplier || ally.IsDead || ally.IsEmbarked)
                continue;
            if (!IsSupplyTruckTargetThresholdMet(ally, out int score, supplierProfile))
                continue;

            Vector3Int allyCell = ally.CurrentCellPosition;
            allyCell.z = 0;
            int distance = GetHexDistance(snapshot.BoardTilemap, supplierCell, allyCell, 64);
            if (distance == int.MaxValue)
                distance = 64;

            bool better = distance < navBestDistance || (distance == navBestDistance && score > navBestScore);
            if (!better)
                continue;

            navBestDistance = distance;
            navBestScore = score;
            target = ally;
        }

        return target != null;
    }
    private bool CanSupplyTargetNow(UnitManager supplier, UnitManager target)
    {
        if (supplier == null || target == null || turnStateManager == null)
            return false;

        List<PodeSuprirOption> options = new List<PodeSuprirOption>();
        if (!turnStateManager.TryGetSupplyTargets(supplier, options, out _) || options.Count <= 0)
            return false;

        for (int i = 0; i < options.Count; i++)
        {
            PodeSuprirOption option = options[i];
            if (option == null || option.targetUnit == null)
                continue;
            if (option.targetUnit == target)
                return true;
        }

        return false;
    }

    private bool TryResolveSupplyObjectiveCell(
        UnitManager supplier,
        UnitManager target,
        AISnapshot snapshot,
        HashSet<Vector3Int> occupiedByAllies,
        HashSet<Vector3Int> preferredCells,
        HashSet<Vector3Int> penalizedCells,
        out Vector3Int objectiveCell,
        out bool actionNow)
    {
        objectiveCell = default;
        actionNow = false;
        if (supplier == null || target == null || snapshot == null || snapshot.BoardTilemap == null)
            return false;

        Vector3Int supplierCell = supplier.CurrentCellPosition;
        supplierCell.z = 0;
        if (CanSupplyTargetNow(supplier, target))
        {
            objectiveCell = supplierCell;
            actionNow = true;
            return true;
        }

        Vector3Int targetCell = target.CurrentCellPosition;
        targetCell.z = 0;
        List<Vector3Int> neighbors = new List<Vector3Int>(6);
        UnitMovementPathRules.GetImmediateHexNeighbors(snapshot.BoardTilemap, targetCell, neighbors);

        int bestScore = int.MinValue;
        int bestDistance = int.MaxValue;
        bool found = false;

        for (int i = 0; i < neighbors.Count; i++)
        {
            Vector3Int candidate = neighbors[i];
            candidate.z = 0;

            if ((occupiedByAllies != null && occupiedByAllies.Contains(candidate))
                || IsCellOccupiedBySnapshotUnit(snapshot, supplier, target, candidate))
                continue;

            int distance = GetHexDistance(snapshot.BoardTilemap, supplierCell, candidate, 64);
            if (distance == int.MaxValue)
                distance = 64;

            int score = -distance * 100;
            if (turnStateManager != null && turnStateManager.IsAutomatedMovementCellReachable(candidate))
                score += 1500;
            if (preferredCells != null && preferredCells.Contains(candidate))
                score += 250;
            if (penalizedCells != null && penalizedCells.Contains(candidate))
                score -= 500;

            bool better = !found || score > bestScore || (score == bestScore && distance < bestDistance);
            if (!better)
                continue;

            bestScore = score;
            bestDistance = distance;
            objectiveCell = candidate;
            found = true;
        }

        return found;
    }

    private static bool IsCellOccupiedBySnapshotUnit(AISnapshot snapshot, UnitManager supplier, UnitManager supplyTarget, Vector3Int cell)
    {
        if (snapshot == null)
            return false;

        cell.z = 0;
        if (snapshot.FriendlyUnits != null)
        {
            for (int i = 0; i < snapshot.FriendlyUnits.Count; i++)
            {
                UnitManager ally = snapshot.FriendlyUnits[i];
                if (ally == null || ally.IsDead || ally == supplier || ally == supplyTarget)
                    continue;

                Vector3Int allyCell = ally.CurrentCellPosition;
                allyCell.z = 0;
                if (allyCell == cell)
                    return true;
            }
        }

        if (snapshot.VisibleEnemies != null)
        {
            for (int i = 0; i < snapshot.VisibleEnemies.Count; i++)
            {
                UnitManager enemy = snapshot.VisibleEnemies[i];
                if (enemy == null || enemy.IsDead)
                    continue;

                Vector3Int enemyCell = enemy.CurrentCellPosition;
                enemyCell.z = 0;
                if (enemyCell == cell)
                    return true;
            }
        }

        return false;
    }

    private bool TryResolveMergeObjectiveForRepairingUnit(UnitManager unit, AISnapshot snapshot, out UnitManager target, out Vector3Int objectiveCell, out bool actionNow, out string label)
    {
        target = null;
        objectiveCell = unit != null ? unit.CurrentCellPosition : Vector3Int.zero;
        actionNow = false;
        label = string.Empty;
        if (unit == null || snapshot == null || snapshot.BoardTilemap == null)
            return false;

        if (TryGetImmediateMergeTargetForRepairingUnit(unit, snapshot, out target, out label))
        {
            objectiveCell = unit.CurrentCellPosition;
            objectiveCell.z = 0;
            actionNow = true;
            return true;
        }

        if (!TryGetMergeApproachTargetForRepairingUnit(unit, snapshot, out target, out objectiveCell, out label))
            return false;

        objectiveCell.z = 0;
        actionNow = false;
        return true;
    }

    private bool TryGetImmediateMergeTargetForRepairingUnit(UnitManager unit, AISnapshot snapshot, out UnitManager target, out string label)
    {
        target = null;
        label = string.Empty;
        if (unit == null || snapshot == null || snapshot.BoardTilemap == null)
            return false;

        List<PodeFundirOption> mergeOptions = new List<PodeFundirOption>();
        if (!PodeFundirSensor.CollectOptions(unit, snapshot.BoardTilemap, turnStateManager != null ? turnStateManager.TerrainDatabaseRef : null, Mathf.Max(0, unit.RemainingMovementPoints), mergeOptions, out _) || mergeOptions.Count <= 0)
            return false;

        int bestCombinedHp = int.MinValue;
        for (int i = 0; i < mergeOptions.Count; i++)
        {
            PodeFundirOption option = mergeOptions[i];
            UnitManager candidate = option != null ? option.candidateUnit : null;
            if (candidate == null || candidate.IsDead)
                continue;

            int combinedHp = Mathf.Max(0, unit.CurrentHP) + Mathf.Max(0, candidate.CurrentHP);
            if (combinedHp > 10)
                continue;

            if (combinedHp <= bestCombinedHp)
                continue;

            bestCombinedHp = combinedHp;
            target = candidate;
        }

        if (target == null)
            return false;

        label = $"fusao com {target.name} (hp total={Mathf.Max(0, unit.CurrentHP) + Mathf.Max(0, target.CurrentHP)})";
        return true;
    }

    private bool TryGetMergeApproachTargetForRepairingUnit(UnitManager unit, AISnapshot snapshot, out UnitManager target, out Vector3Int objectiveCell, out string label)
    {
        target = null;
        objectiveCell = unit != null ? unit.CurrentCellPosition : Vector3Int.zero;
        label = string.Empty;
        if (unit == null || snapshot == null || snapshot.BoardTilemap == null)
            return false;

        Tilemap boardTilemap = snapshot.BoardTilemap;
        TerrainDatabase terrainDb = turnStateManager != null ? turnStateManager.TerrainDatabaseRef : null;
        int remainingMovement = Mathf.Max(0, unit.RemainingMovementPoints);
        if (remainingMovement <= 0)
            return false;

        Dictionary<Vector3Int, List<Vector3Int>> reachablePaths = UnitMovementPathRules.CalcularCaminhosValidos(
            boardTilemap,
            unit,
            remainingMovement,
            terrainDb);
        if (reachablePaths == null || reachablePaths.Count <= 0)
            return false;

        int bestApproachCost = int.MaxValue;
        int bestCandidateDistance = int.MaxValue;
        int bestCombinedHp = int.MinValue;
        List<Vector3Int> neighbors = new List<Vector3Int>(6);
        IReadOnlyList<UnitManager> friendlyUnits = snapshot.FriendlyUnits;
        for (int i = 0; friendlyUnits != null && i < friendlyUnits.Count; i++)
        {
            UnitManager candidate = friendlyUnits[i];
            if (!CanRepairModeMergeWithCandidate(unit, candidate))
                continue;

            int combinedHp = Mathf.Max(0, unit.CurrentHP) + Mathf.Max(0, candidate.CurrentHP);
            if (combinedHp > 10)
                continue;

            Vector3Int candidateCell = candidate.CurrentCellPosition;
            candidateCell.z = 0;
            if (!UnitMovementPathRules.TryGetEnterCellCost(
                    boardTilemap,
                    unit,
                    candidateCell,
                    terrainDb,
                    applyOperationalAutonomyModifier: false,
                    out int enterCost))
                continue;

            UnitMovementPathRules.GetImmediateHexNeighbors(boardTilemap, candidateCell, neighbors);
            for (int n = 0; n < neighbors.Count; n++)
            {
                Vector3Int approachCell = neighbors[n];
                approachCell.z = 0;
                if (!reachablePaths.TryGetValue(approachCell, out List<Vector3Int> path) || path == null || path.Count <= 0)
                    continue;

                int approachCost = Mathf.Max(0, UnitMovementPathRules.CalculateAutonomyCostForPath(
                    boardTilemap,
                    unit,
                    path,
                    terrainDb,
                    applyOperationalAutonomyModifier: false));
                int remainingAfterApproach = Mathf.Max(0, remainingMovement - approachCost);
                if (remainingAfterApproach < enterCost)
                    continue;

                int candidateDistance = GetHexDistance(boardTilemap, unit.CurrentCellPosition, candidateCell, 64);
                bool better = approachCost < bestApproachCost
                    || (approachCost == bestApproachCost && candidateDistance < bestCandidateDistance)
                    || (approachCost == bestApproachCost && candidateDistance == bestCandidateDistance && combinedHp > bestCombinedHp);
                if (!better)
                    continue;

                bestApproachCost = approachCost;
                bestCandidateDistance = candidateDistance;
                bestCombinedHp = combinedHp;
                target = candidate;
                objectiveCell = candidateCell;
            }
        }

        if (target == null)
            return false;

        label = $"aproximar para fusao com {target.name} (hp total={Mathf.Max(0, unit.CurrentHP) + Mathf.Max(0, target.CurrentHP)})";
        return true;
    }

    private static bool CanRepairModeMergeWithCandidate(UnitManager unit, UnitManager candidate)
    {
        if (unit == null || candidate == null || candidate == unit || candidate.IsDead || candidate.IsEmbarked)
            return false;
        if (!candidate.gameObject.activeInHierarchy)
            return false;
        if ((int)unit.TeamId != (int)candidate.TeamId)
            return false;
        if (!AreUnitsSameTypeForAiMerge(unit, candidate))
            return false;
        if (HasAnyTransportedPassenger(candidate))
            return false;
        return unit.GetDomain() == candidate.GetDomain()
            && unit.GetHeightLevel() == candidate.GetHeightLevel();
    }

    private static bool AreUnitsSameTypeForAiMerge(UnitManager a, UnitManager b)
    {
        if (a == null || b == null)
            return false;

        string aId = a.UnitId;
        string bId = b.UnitId;
        if (!string.IsNullOrWhiteSpace(aId) && !string.IsNullOrWhiteSpace(bId))
            return string.Equals(aId.Trim(), bId.Trim(), System.StringComparison.OrdinalIgnoreCase);

        if (a.TryGetUnitData(out UnitData aData) && b.TryGetUnitData(out UnitData bData))
            return aData != null && bData != null && aData == bData;

        return false;
    }

    private static bool HasAnyTransportedPassenger(UnitManager unit)
    {
        IReadOnlyList<UnitTransportSeatRuntime> seats = unit != null ? unit.TransportedUnitSlots : null;
        if (seats == null)
            return false;

        for (int i = 0; i < seats.Count; i++)
        {
            if (seats[i] != null && seats[i].embarkedUnit != null)
                return true;
        }

        return false;
    }

    private bool TryGetImmediateSupplyTargetsNow(UnitManager supplier, out List<UnitManager> targets)
    {
        return TryCollectPrioritizedSupplyTargetsNow(supplier, null, out targets);
    }

    private bool TryCollectPrioritizedSupplyTargetsNow(UnitManager supplier, UnitManager preferredTarget, out List<UnitManager> targets)
    {
        targets = new List<UnitManager>();
        if (supplier == null || turnStateManager == null)
            return false;

        List<PodeSuprirOption> sensorOptions = new List<PodeSuprirOption>();
        if (!turnStateManager.TryGetSupplyTargets(supplier, sensorOptions, out _) || sensorOptions.Count <= 0)
            return false;

        int queueLimit = 1;
        AIUnitProfile supplierProfile = null;
        if (supplier.TryGetUnitData(out UnitData supplierData) && supplierData != null)
        {
            queueLimit = Mathf.Max(1, supplierData.maxUnitsServedPerTurn);
            supplierProfile = supplierData.aiUnitProfile;
        }

        Vector3Int supplierCell = supplier.CurrentCellPosition;
        supplierCell.z = 0;

        List<(UnitManager target, int distance, int score)> ranked = new List<(UnitManager target, int distance, int score)>();
        HashSet<int> seen = new HashSet<int>();
        for (int i = 0; i < sensorOptions.Count; i++)
        {
            UnitManager candidate = sensorOptions[i] != null ? sensorOptions[i].targetUnit : null;
            if (candidate == null || candidate.IsDead || !seen.Add(candidate.InstanceId))
                continue;

            bool isPreferred = preferredTarget != null && candidate == preferredTarget;
            int score = 0;
            if (!IsSupplyTruckTargetThresholdMet(candidate, out score, supplierProfile))
            {
                if (!isPreferred)
                    continue;

                // Mantem coerencia entre a decisao tomada antes do movimento e a execucao final.
                score = 100000;
            }
            else if (isPreferred)
            {
                score += 100000;
            }

            Tilemap boardTilemap = supplier.BoardTilemap != null ? supplier.BoardTilemap : candidate.BoardTilemap;
            Vector3Int candidateCell = candidate.CurrentCellPosition;
            candidateCell.z = 0;
            int distance = boardTilemap != null
                ? GetHexDistance(boardTilemap, supplierCell, candidateCell, 64)
                : 64;
            if (distance == int.MaxValue)
                distance = 64;

            ranked.Add((candidate, distance, score));
        }

        ranked.Sort((a, b) =>
        {
            int distanceCompare = a.distance.CompareTo(b.distance);
            if (distanceCompare != 0)
                return distanceCompare;
            return b.score.CompareTo(a.score);
        });
        for (int i = 0; i < ranked.Count && targets.Count < queueLimit; i++)
            targets.Add(ranked[i].target);

        return targets.Count > 0;
    }
    private static bool IsSupplyTruckTargetThresholdMet(UnitManager ally, out int score, AIUnitProfile supplierProfile = null)
    {
        score = 0;
        if (ally == null || ally.IsDead)
            return false;

        int fuelThresholdPct = supplierProfile != null ? supplierProfile.supplyAllyFuelThresholdPercent : 25;
        int ammoThresholdPct = supplierProfile != null ? supplierProfile.supplyAllyAmmoThresholdPercent : 0;
        int hpThresholdPct   = supplierProfile != null ? supplierProfile.supplyAllyHpThresholdPercent   : 50;

        int maxHp = Mathf.Max(1, ally.GetMaxHP());
        bool lowHp = hpThresholdPct > 0 && ally.CurrentHP * 100 < maxHp * hpThresholdPct;

        bool lowAmmo = false;
        int ammoCurrentTotal = 0;
        int ammoMaxTotal = 0;
        IReadOnlyList<UnitEmbarkedWeapon> runtimeWeapons = ally.GetEmbarkedWeapons();
        if (runtimeWeapons != null && runtimeWeapons.Count > 0)
        {
            if (ally.TryGetUnitData(out UnitData allyData) && allyData != null && allyData.embarkedWeapons != null)
            {
                int count = Mathf.Min(runtimeWeapons.Count, allyData.embarkedWeapons.Count);
                for (int i = 0; i < count; i++)
                {
                    UnitEmbarkedWeapon runtime = runtimeWeapons[i];
                    UnitEmbarkedWeapon baseline = allyData.embarkedWeapons[i];
                    if (runtime == null || baseline == null || baseline.weapon == null)
                        continue;

                    int maxAmmo = Mathf.Max(0, baseline.squadAmmunition);
                    if (maxAmmo <= 0)
                        continue;

                    ammoMaxTotal += maxAmmo;
                    ammoCurrentTotal += Mathf.Clamp(runtime.squadAmmunition, 0, maxAmmo);
                }
            }
        }

        if (ammoMaxTotal > 0)
        {
            int ammoPercentCurrent = ammoCurrentTotal * 100 / ammoMaxTotal;
            lowAmmo = ammoPercentCurrent <= ammoThresholdPct;
        }

        int maxFuel = ally.GetMaxFuel();
        bool lowAutonomy = false;
        if (maxFuel > 0 && fuelThresholdPct > 0)
            lowAutonomy = ally.CurrentFuel * 100 <= maxFuel * fuelThresholdPct;

        if (!lowHp && !lowAmmo && !lowAutonomy)
            return false;

        int hpMissing   = Mathf.Max(0, maxHp - ally.CurrentHP);
        int ammoMissing = Mathf.Max(0, ammoMaxTotal - ammoCurrentTotal);
        int fuelMissing = maxFuel > 0 ? Mathf.Max(0, maxFuel - ally.CurrentFuel) : 0;
        score = hpMissing * 120 + ammoMissing * 45 + fuelMissing * 35
            + (lowHp ? 5000 : 0) + (lowAmmo ? 3000 : 0) + (lowAutonomy ? 2500 : 0);
        return true;
    }
    private bool TryGetSupplyTruckDefensivePatrolCell(UnitManager unit, AISnapshot snapshot, out Vector3Int targetCell)
    {
        targetCell = default;
        if (unit == null || snapshot == null || snapshot.BoardTilemap == null || !snapshot.HasHq)
            return false;

        Vector3Int unitCell = unit.CurrentCellPosition;
        unitCell.z = 0;
        Vector3Int hqCell = snapshot.HqCell;
        hqCell.z = 0;

        List<Vector3Int> frontier = new List<Vector3Int> { hqCell };
        HashSet<Vector3Int> visited = new HashSet<Vector3Int> { hqCell };
        List<Vector3Int> neighbors = new List<Vector3Int>(6);

        int bestDistToUnit = int.MaxValue;
        int bestDistToHq = int.MaxValue;
        Vector3Int best = default;
        bool found = false;

        for (int depth = 0; depth < 3; depth++)
        {
            List<Vector3Int> nextFrontier = new List<Vector3Int>();
            for (int i = 0; i < frontier.Count; i++)
            {
                Vector3Int current = frontier[i];
                UnitMovementPathRules.GetImmediateHexNeighbors(snapshot.BoardTilemap, current, neighbors);
                for (int n = 0; n < neighbors.Count; n++)
                {
                    Vector3Int cell = neighbors[n];
                    cell.z = 0;
                    if (visited.Contains(cell))
                        continue;
                    visited.Add(cell);
                    nextFrontier.Add(cell);

                    if (IsFriendlyConstructionCell(snapshot, unit.TeamId, cell))
                        continue;

                    int distToHq = GetHexDistance(snapshot.BoardTilemap, hqCell, cell, 32);
                    if (distToHq == int.MaxValue || distToHq <= 0 || distToHq > 2)
                        continue;

                    int distToUnit = GetHexDistance(snapshot.BoardTilemap, unitCell, cell, 64);
                    if (distToUnit == int.MaxValue)
                        continue;

                    bool better = !found
                        || distToUnit < bestDistToUnit
                        || (distToUnit == bestDistToUnit && distToHq < bestDistToHq);
                    if (!better)
                        continue;

                    found = true;
                    bestDistToUnit = distToUnit;
                    bestDistToHq = distToHq;
                    best = cell;
                }
            }

            frontier = nextFrontier;
            if (frontier.Count <= 0)
                break;
        }

        if (!found)
            return false;

        targetCell = best;
        targetCell.z = 0;
        return true;
    }

    private static bool IsFriendlyConstructionCell(AISnapshot snapshot, TeamId team, Vector3Int cell)
    {
        if (snapshot == null || snapshot.KnownConstructions == null)
            return false;

        cell.z = 0;
        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Source == null)
                continue;
            if (info.TeamId != team)
                continue;

            Vector3Int c = info.Cell;
            c.z = 0;
            if (c == cell)
                return true;
        }

        return false;
    }

    private static bool IsFriendlyCaptureUnitOccupyingCell(AISnapshot snapshot, UnitManager requester, Vector3Int cell)
    {
        if (snapshot == null || requester == null || snapshot.FriendlyUnits == null)
            return false;

        cell.z = 0;
        for (int i = 0; i < snapshot.FriendlyUnits.Count; i++)
        {
            UnitManager ally = snapshot.FriendlyUnits[i];
            if (ally == null || ally == requester || ally.IsDead || ally.IsEmbarked)
                continue;
            if (ally.TeamId != requester.TeamId)
                continue;
            if (!(ally.TryGetUnitData(out UnitData allyData) && allyData != null
                && allyData.aiUnitProfile != null && allyData.aiUnitProfile.HasSensorInStance(AIStance.Attack, AIUnitSensorKind.Capture)))
                continue;

            Vector3Int allyCell = ally.CurrentCellPosition;
            allyCell.z = 0;
            if (allyCell == cell)
                return true;
        }

        return false;
    }

    private static bool ShouldKeepUnitInRepairMode(UnitManager unit)
    {
        if (unit == null || unit.IsDead)
            return false;

        unit.TryGetUnitData(out UnitData data);
        AIUnitProfile profile = data?.aiUnitProfile;
        int enterThreshold = profile != null ? profile.hpRepairThreshold    : 3;
        int exitThreshold  = profile != null ? profile.hpRepairExitThreshold : 8;

        if (enterThreshold <= 0)
        {
            if (unit.AIForcedToRepair)
                unit.SetAIForcedToRepair(false);
            return false;
        }

        bool forced = unit.AIForcedToRepair;

        if (!forced && unit.CurrentHP <= enterThreshold)
            forced = true;
        if (!forced && IsLowAutonomy(unit, profile) && !(data != null && data.isSupplier))
            forced = true;
        if (!forced && IsOutOfCombatAmmo(unit, profile))
            forced = true;

        if (forced)
        {
            bool hpOk   = unit.CurrentHP >= exitThreshold;
            bool fuelOk = !IsLowAutonomy(unit, profile);
            bool ammoOk = !IsOutOfCombatAmmo(unit, profile);
            if (hpOk && fuelOk && ammoOk)
                forced = false;
        }

        if (unit.AIForcedToRepair != forced)
            unit.SetAIForcedToRepair(forced);

        return forced;
    }

    private AIInitiative GetEffectiveInitiative(UnitManager unit)
    {
        if (unit == null)
            return AIInitiative.Medium;

        if (ShouldKeepUnitInRepairMode(unit))
            return AIInitiative.Retreat;

        if (unit.TryGetUnitData(out UnitData data) && data?.aiUnitProfile != null)
            return data.aiUnitProfile.initiative;

        return AIInitiative.Medium;
    }
    private static bool IsLowAutonomy(UnitManager unit, AIUnitProfile profile = null)
    {
        if (unit == null)
            return false;
        int maxFuel = unit.GetMaxFuel();
        if (maxFuel <= 0)
            return false;
        int threshold = profile != null ? profile.repairAutonomyThresholdPercent : 25;
        if (threshold <= 0)
            return false;
        return unit.CurrentFuel * 100 <= maxFuel * threshold;
    }

    private static bool IsOutOfCombatAmmo(UnitManager unit, AIUnitProfile profile = null)
    {
        if (unit == null)
            return false;

        bool anyWeapon = profile == null || profile.repairWhenAnyWeaponOutOfAmmo;

        IReadOnlyList<UnitEmbarkedWeapon> weapons = unit.GetEmbarkedWeapons();
        if (weapons == null || weapons.Count == 0)
            return false;

        bool hasAmmoBasedWeapon = false;
        for (int i = 0; i < weapons.Count; i++)
        {
            UnitEmbarkedWeapon w = weapons[i];
            if (w == null || w.weapon == null)
                continue;

            hasAmmoBasedWeapon = true;
            if (w.squadAmmunition <= 0)
            {
                if (anyWeapon)
                    return true; // qualquer arma zerada ja dispara
            }
            else if (!anyWeapon)
            {
                return false; // todas precisam estar zeradas; esta nao esta
            }
        }

        // anyWeapon=true e nenhuma zerada Ã¢â€ â€™ false. anyWeapon=false e todas zeradas Ã¢â€ â€™ hasAmmoBasedWeapon.
        return !anyWeapon && hasAmmoBasedWeapon;
    }

    private bool CanReachAndAttackThisTurn(
        UnitManager attacker,
        UnitManager enemy,
        AISnapshot snapshot,
        HashSet<Vector3Int> occupiedByAllies,
        Vector3Int attackerCell)
    {
        if (attacker == null || enemy == null || enemy.IsDead || snapshot == null || snapshot.BoardTilemap == null)
            return false;

        TerrainDatabase terrainDb = turnStateManager != null ? turnStateManager.TerrainDatabaseRef : null;
        int moveBudget = Mathf.Max(0, attacker.RemainingMovementPoints);
        Dictionary<Vector3Int, List<Vector3Int>> paths = UnitMovementPathRules.CalcularCaminhosValidos(
            snapshot.BoardTilemap,
            attacker,
            moveBudget,
            terrainDb);
        if (paths == null || paths.Count <= 0)
            return false;

        Vector3Int enemyCell = enemy.CurrentCellPosition;
        enemyCell.z = 0;
        attackerCell.z = 0;
        List<int> distances = new List<int>(8);
        return TryCollectReachableAttackDistances(
            snapshot.BoardTilemap,
            attacker,
            enemy,
            attackerCell,
            enemyCell,
            paths,
            occupiedByAllies,
            distances);
    }

    private bool TryGetBestRepairDislodgeTarget(
        UnitManager unit,
        AISnapshot snapshot,
        HashSet<Vector3Int> occupiedByAllies,
        Vector3Int unitCell,
        out UnitManager target,
        out string reason)
    {
        target = null;
        reason = string.Empty;

        if (unit == null || snapshot == null || snapshot.VisibleEnemies == null || snapshot.VisibleEnemies.Count <= 0)
            return false;
        if (!unit.TryGetUnitData(out UnitData attackerData) || attackerData == null)
            return false;

        RPSDatabase rpsDb = turnStateManager != null ? turnStateManager.RpsDatabaseRef : null;
        DPQMatchupDatabase dpqDb = turnStateManager != null ? turnStateManager.DpqMatchupDatabaseRef : null;
        WeaponPriorityData wpDb = turnStateManager != null ? turnStateManager.WeaponPriorityDataRef : null;
        if (rpsDb == null || dpqDb == null || wpDb == null)
            return false;

        int bestScore = int.MinValue;
        UnitManager best = null;

        for (int i = 0; i < snapshot.VisibleEnemies.Count; i++)
        {
            UnitManager enemy = snapshot.VisibleEnemies[i];
            if (enemy == null || enemy.IsDead)
                continue;
            if (!IsEnemyOccupyingOwnedConstructionForMyTeam(snapshot, unit, enemy))
                continue;
            if (!CanReachAndAttackThisTurn(unit, enemy, snapshot, occupiedByAllies, unitCell))
                continue;
            if (!enemy.TryGetUnitData(out UnitData defenderData) || defenderData == null)
                continue;

            Vector3Int enemyCell = enemy.CurrentCellPosition;
            enemyCell.z = 0;
            int rawDist = GetHexDistance(snapshot.BoardTilemap, unitCell, enemyCell, 64);
            if (rawDist == int.MaxValue)
                continue;

            List<int> reachableDistances = new List<int>(8);
            int moveBudget = Mathf.Max(0, unit.RemainingMovementPoints);
        UnitCombatClassification combatClassification = unit != null ? unit.CombatClassification : UnitCombatClassification.Civil;
            Dictionary<Vector3Int, List<Vector3Int>> paths = UnitMovementPathRules.CalcularCaminhosValidos(
                snapshot.BoardTilemap,
                unit,
                moveBudget,
                turnStateManager != null ? turnStateManager.TerrainDatabaseRef : null);
            if (!TryCollectReachableAttackDistances(snapshot.BoardTilemap, unit, enemy, unitCell, enemyCell, paths, occupiedByAllies, reachableDistances))
                continue;

            int score = EvaluateAttackTargetScore(
                attackerData,
                defenderData,
                unit.CurrentHP,
                enemy.CurrentHP,
                rawDist,
                reachableDistances,
                currentStance == AIStance.Defend,
                rpsDb,
                dpqDb,
                wpDb,
                out _);

            if (score < 26000)
                continue;
            if (score <= bestScore)
                continue;

            bestScore = score;
            best = enemy;
        }

        if (best == null)
            return false;

        target = best;
        reason = "desocupar construcao propria para reparar";
        return true;
    }

    private bool TryGetRepairFallbackCell(
        UnitManager unit,
        AISnapshot snapshot,
        out Vector3Int targetCell,
        out string label)
    {
        targetCell = default;
        label = string.Empty;

        if (unit == null || snapshot == null)
            return false;

        if (snapshot.HasHq)
        {
            targetCell = snapshot.HqCell;
            targetCell.z = 0;
            label = "HQ (fallback defensivo)";
            return true;
        }

        targetCell = unit.CurrentCellPosition;
        targetCell.z = 0;
        label = "fallback local";
        return true;
    }

    private static bool IsEnemyOccupyingOwnedConstructionForMyTeam(AISnapshot snapshot, UnitManager attacker, UnitManager enemy)
    {
        if (snapshot == null || attacker == null || enemy == null)
            return false;

        return TryGetEnemyOccupyingOwnedConstruction(snapshot, attacker.TeamId, enemy.CurrentCellPosition, out _);
    }

    private static bool TryGetEnemyOccupyingOwnedConstruction(AISnapshot snapshot, TeamId myTeam, Vector3Int enemyCell, out AIConstructionInfo occupiedInfo)
    {
        occupiedInfo = null;
        if (snapshot == null || snapshot.KnownConstructions == null)
            return false;

        enemyCell.z = 0;
        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Source == null)
                continue;

            Vector3Int constructionCell = info.Cell;
            constructionCell.z = 0;
            if (constructionCell != enemyCell)
                continue;
            if (!info.Source.IsCapturable || info.Source.CapturePointsMax <= 0)
                continue;
            if (info.TeamId != myTeam)
                continue;

            occupiedInfo = info;
            return true;
        }

        return false;
    }

    private bool TryGetNearestOwnedConstruction(
        UnitManager unit,
        AISnapshot snapshot,
        out ConstructionManager targetConstruction,
        out Vector3Int targetCell,
        out string targetLabel)
    {
        targetConstruction = null;
        targetCell = default;
        targetLabel = string.Empty;

        if (unit == null || snapshot == null || snapshot.KnownConstructions == null || snapshot.KnownConstructions.Count == 0)
            return false;

        TeamId myTeam = unit.TeamId;
        Vector3Int unitCell = unit.CurrentCellPosition;
        unitCell.z = 0;

        int bestDistance = int.MaxValue;
        AIConstructionInfo bestInfo = null;

        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Source == null)
                continue;
            if (info.TeamId != myTeam)
                continue;
            if (TryGetBlockingShoppingOccupant(info.Source, out UnitManager blocker) && blocker != null && blocker != unit)
                continue;

            Vector3Int cell = info.Cell;
            cell.z = 0;
            int distance = GetHexDistance(snapshot.BoardTilemap, unitCell, cell, 64);
            if (distance == int.MaxValue)
                distance = 64;

            if (distance >= bestDistance)
                continue;

            bestDistance = distance;
            bestInfo = info;
        }

        if (bestInfo == null || bestInfo.Source == null)
            return false;

        targetConstruction = bestInfo.Source;
        targetCell = bestInfo.Cell;
        targetCell.z = 0;
        targetLabel = !string.IsNullOrWhiteSpace(bestInfo.DisplayName) ? bestInfo.DisplayName : bestInfo.Source.name;
        return true;
    }

    private bool TryEvaluateReachableAttackScore(
        UnitManager attacker,
        UnitManager enemy,
        AISnapshot snapshot,
        HashSet<Vector3Int> occupiedByAllies,
        out int score)
    {
        score = int.MinValue / 4;
        if (attacker == null || enemy == null || enemy.IsDead || snapshot == null || snapshot.BoardTilemap == null)
            return false;
        if (!attacker.TryGetUnitData(out UnitData attackerData) || attackerData == null)
            return false;
        if (!enemy.TryGetUnitData(out UnitData defenderData) || defenderData == null)
            return false;

        RPSDatabase rpsDb = turnStateManager != null ? turnStateManager.RpsDatabaseRef : null;
        DPQMatchupDatabase dpqDb = turnStateManager != null ? turnStateManager.DpqMatchupDatabaseRef : null;
        WeaponPriorityData wpDb = turnStateManager != null ? turnStateManager.WeaponPriorityDataRef : null;
        TerrainDatabase terrainDb = turnStateManager != null ? turnStateManager.TerrainDatabaseRef : null;
        if (rpsDb == null || dpqDb == null || wpDb == null)
            return false;

        int moveBudget = Mathf.Max(0, attacker.RemainingMovementPoints);
        Dictionary<Vector3Int, List<Vector3Int>> paths = UnitMovementPathRules.CalcularCaminhosValidos(
            snapshot.BoardTilemap,
            attacker,
            moveBudget,
            terrainDb);
        if (paths == null || paths.Count <= 0)
            return false;

        Vector3Int attackerCell = attacker.CurrentCellPosition;
        attackerCell.z = 0;
        Vector3Int enemyCell = enemy.CurrentCellPosition;
        enemyCell.z = 0;
        List<int> reachableAttackDistances = new List<int>(8);
        if (!TryCollectReachableAttackDistances(
                snapshot.BoardTilemap,
                attacker,
                enemy,
                attackerCell,
                enemyCell,
                paths,
                occupiedByAllies,
                reachableAttackDistances))
            return false;

        int tieDistance = GetHexDistance(snapshot.BoardTilemap, attackerCell, enemyCell, 64);
        if (tieDistance == int.MaxValue)
            tieDistance = 64;

        score = EvaluateAttackTargetScore(
            attackerData,
            defenderData,
            attacker.CurrentHP,
            enemy.CurrentHP,
            tieDistance,
            reachableAttackDistances,
            currentStance == AIStance.Defend,
            rpsDb,
            dpqDb,
            wpDb,
            out _);

        return score > (int.MinValue / 8);
    }

    private static bool IsEscortMissionRole(AIPlanRole role)
    {
        return role == AIPlanRole.Escort
            || role == AIPlanRole.Artillery
            || role == AIPlanRole.Support;
    }

    private static bool HasVisibleEnemyOnCell(AISnapshot snapshot, Vector3Int cell)
    {
        if (snapshot?.VisibleEnemies == null) return false;
        cell.z = 0;
        for (int i = 0; i < snapshot.VisibleEnemies.Count; i++)
        {
            UnitManager e = snapshot.VisibleEnemies[i];
            if (e == null || e.IsDead) continue;
            Vector3Int ec = e.CurrentCellPosition;
            ec.z = 0;
            if (ec == cell) return true;
        }
        return false;
    }

    private static UnitManager GetVisibleEnemyOnCell(AISnapshot snapshot, Vector3Int cell)
    {
        if (snapshot?.VisibleEnemies == null) return null;
        cell.z = 0;
        for (int i = 0; i < snapshot.VisibleEnemies.Count; i++)
        {
            UnitManager e = snapshot.VisibleEnemies[i];
            if (e == null || e.IsDead) continue;
            Vector3Int ec = e.CurrentCellPosition;
            ec.z = 0;
            if (ec == cell) return e;
        }
        return null;
    }

    private static bool IsEnemyInCaptureLane(
        Tilemap board,
        Vector3Int unitCell,
        Vector3Int captureObjectiveCell,
        Vector3Int enemyCell)
    {
        unitCell.z = 0;
        captureObjectiveCell.z = 0;
        enemyCell.z = 0;

        int unitToObjective = GetHexDistance(board, unitCell, captureObjectiveCell, 64);
        int enemyToObjective = GetHexDistance(board, enemyCell, captureObjectiveCell, 64);
        int unitToEnemy = GetHexDistance(board, unitCell, enemyCell, 64);
        if (unitToObjective == int.MaxValue || enemyToObjective == int.MaxValue || unitToEnemy == int.MaxValue)
            return false;

        if (enemyToObjective <= 1)
            return true;

        return unitToEnemy <= unitToObjective + 1 && enemyToObjective <= unitToObjective;
    }
    private int GetEscortThreatPriority(
        UnitManager escortUnit,
        UnitManager enemy,
        AISnapshot snapshot,
        AIPlanIntent intent,
        Vector3Int cohesionCell,
        out string reason)
    {
        reason = string.Empty;

        if (escortUnit == null || enemy == null || snapshot == null)
            return int.MaxValue;

        Vector3Int escortCell = escortUnit.CurrentCellPosition;
        escortCell.z = 0;
        Vector3Int enemyCell = enemy.CurrentCellPosition;
        enemyCell.z = 0;
        cohesionCell.z = 0;

        if (intent != null)
        {
            if (intent.Assignments != null)
            {
                for (int i = 0; i < intent.Assignments.Count; i++)
                {
                    AIPlanAssignment asgn = intent.Assignments[i];
                    if (asgn == null || asgn.Role != AIPlanRole.Capture)
                        continue;

                    UnitManager captureUnit = FindUnitById(asgn.UnitInstanceId);
                    if (captureUnit != null && !captureUnit.IsDead)
                    {
                        Vector3Int captureCell = captureUnit.CurrentCellPosition;
                        captureCell.z = 0;
                        int toCaptureUnit = GetHexDistance(snapshot.BoardTilemap, captureCell, enemyCell, 64);
                        if (toCaptureUnit != int.MaxValue && toCaptureUnit <= 4)
                        {
                            reason = $"ameaca-ao-capturador d={toCaptureUnit}";
                            return 0;
                        }
                    }

                    if (asgn.HasPlannedCaptureTarget)
                    {
                        Vector3Int plannedCell = asgn.PlannedCaptureCell;
                        plannedCell.z = 0;
                        int toPlanned = GetHexDistance(snapshot.BoardTilemap, plannedCell, enemyCell, 64);
                        if (toPlanned != int.MaxValue && toPlanned <= 4)
                        {
                            reason = $"ameaca-ao-objetivo-planejado d={toPlanned}";
                            return 1;
                        }
                    }
                }
            }

            if (intent.HasCaptureTarget)
            {
                Vector3Int captureTarget = intent.CaptureTargetCell;
                captureTarget.z = 0;
                int toCaptureTarget = GetHexDistance(snapshot.BoardTilemap, captureTarget, enemyCell, 64);
                if (toCaptureTarget != int.MaxValue && toCaptureTarget <= 4)
                {
                    reason = $"ameaca-ao-objetivo-do-plano d={toCaptureTarget}";
                    return 1;
                }
            }
        }

        int toCohesion = GetHexDistance(snapshot.BoardTilemap, cohesionCell, enemyCell, 64);
        if (toCohesion != int.MaxValue && toCohesion <= 4)
        {
            reason = $"ameaca-a-coesao d={toCohesion}";
            return 2;
        }

        int toEscort = GetHexDistance(snapshot.BoardTilemap, escortCell, enemyCell, 64);
        if (toEscort != int.MaxValue && toEscort <= 3)
        {
            reason = $"ameaca-imediata-a-escolta d={toEscort}";
            return 3;
        }

        return int.MaxValue;
    }

    private bool IsEscortThreatRelevant(
        UnitManager escortUnit,
        UnitManager enemy,
        AISnapshot snapshot,
        AIPlanIntent intent,
        Vector3Int cohesionCell)
    {
        return GetEscortThreatPriority(escortUnit, enemy, snapshot, intent, cohesionCell, out _) != int.MaxValue;
    }


    private bool TryGetPlanCohesionObjective(
        UnitManager unit,
        AISnapshot snapshot,
        AIPlanIntent unitIntent,
        AIPlanAssignment unitAssignment,
        out Vector3Int targetCell,
        out string targetLabel)
    {
        targetCell = unit.CurrentCellPosition;
        targetCell.z = 0;
        targetLabel = unitIntent != null ? unitIntent.Sector.ToString() : "plano";

        if (unit == null || snapshot == null || unitIntent == null || unitAssignment == null)
            return false;
        if (ConstructionSectorHelper.IsBase(unitIntent.Sector))
            return false;

        Vector3Int unitCell = unit.CurrentCellPosition;
        unitCell.z = 0;
        int bestDistance = int.MaxValue;
        bool found = false;

        // Prioridade 1: escolta acompanha a unidade capturadora do mesmo plano.
        if (unitIntent.Assignments != null)
        {
            for (int i = 0; i < unitIntent.Assignments.Count; i++)
            {
                AIPlanAssignment asgn = unitIntent.Assignments[i];
                if (asgn == null || asgn.UnitInstanceId == unit.InstanceId)
                    continue;
                if (asgn.Role != AIPlanRole.Capture)
                    continue;

                UnitManager captureUnit = FindUnitById(asgn.UnitInstanceId);
                if (captureUnit == null || captureUnit.IsDead)
                    continue;

                Vector3Int candidate = captureUnit.CurrentCellPosition;
                candidate.z = 0;
                int dist = GetHexDistance(snapshot.BoardTilemap, unitCell, candidate, 64);
                if (dist == int.MaxValue) dist = 64;
                if (dist >= bestDistance) continue;

                bestDistance = dist;
                targetCell = candidate;
                targetLabel = captureUnit.name;
                found = true;
            }
        }

        if (found)
            return true;

        // Prioridade 2: objetivo de captura planejado para o setor.
        if (unitIntent.Assignments != null)
        {
            for (int i = 0; i < unitIntent.Assignments.Count; i++)
            {
                AIPlanAssignment asgn = unitIntent.Assignments[i];
                if (asgn == null || asgn.UnitInstanceId == unit.InstanceId)
                    continue;
                if (asgn.Role != AIPlanRole.Capture)
                    continue;

                Vector3Int candidate = asgn.HasPlannedCaptureTarget
                    ? asgn.PlannedCaptureCell
                    : (unitIntent.HasCaptureTarget ? unitIntent.CaptureTargetCell : unitCell);
                candidate.z = 0;
                int dist = GetHexDistance(snapshot.BoardTilemap, unitCell, candidate, 64);
                if (dist == int.MaxValue) dist = 64;
                if (dist >= bestDistance) continue;

                bestDistance = dist;
                targetCell = candidate;
                targetLabel = asgn.HasPlannedCaptureTarget && !string.IsNullOrWhiteSpace(asgn.PlannedCaptureLabel)
                    ? asgn.PlannedCaptureLabel
                    : unitIntent.Sector.ToString();
                found = true;
            }
        }

        if (found)
            return true;

        for (int i = 0; i < snapshot.KnownConstructions.Count; i++)
        {
            AIConstructionInfo info = snapshot.KnownConstructions[i];
            if (info == null || info.Sector != unitIntent.Sector || !info.IsCapturable)
                continue;

            bool aiOwnsFully = info.TeamId == unit.TeamId && info.CapturePoints >= info.CapturePointsMax;
            if (aiOwnsFully)
                continue;

            Vector3Int candidate = info.Cell;
            candidate.z = 0;
            int dist = GetHexDistance(snapshot.BoardTilemap, unitCell, candidate, 64);
            if (dist == int.MaxValue) dist = 64;
            if (dist >= bestDistance) continue;

            bestDistance = dist;
            targetCell = candidate;
            targetLabel = !string.IsNullOrWhiteSpace(info.DisplayName) ? info.DisplayName : unitIntent.Sector.ToString();
            found = true;
        }

        return found;
    }


    private HashSet<Vector3Int> BuildFriendlySupportPreferenceCells(
        AISnapshot snapshot,
        UnitManager requester,
        bool supportOnlyCombatAnchors)
    {
        if (snapshot == null || snapshot.BoardTilemap == null || requester == null || snapshot.FriendlyUnits == null)
            return null;

        HashSet<Vector3Int> seeds = null;
        for (int i = 0; i < snapshot.FriendlyUnits.Count; i++)
        {
            UnitManager ally = snapshot.FriendlyUnits[i];
            if (ally == null || ally.IsDead || ally == requester)
                continue;

            if (supportOnlyCombatAnchors)
            {
                UnitCombatClassification allyClass = ally.CombatClassification;
                if (allyClass != UnitCombatClassification.Combatente && allyClass != UnitCombatClassification.Hibrido)
                    continue;
            }

            if (seeds == null)
                seeds = new HashSet<Vector3Int>();

            Vector3Int cell = ally.CurrentCellPosition;
            cell.z = 0;
            seeds.Add(cell);
        }

        if (seeds == null || seeds.Count == 0)
            return null;

        return ExpandCellsByHexRadius(snapshot.BoardTilemap, seeds, 1);
    }

    private HashSet<Vector3Int> BuildEnemyDangerCells(AISnapshot snapshot, int radius)
    {
        if (snapshot == null || snapshot.BoardTilemap == null || snapshot.VisibleEnemies == null || snapshot.VisibleEnemies.Count == 0)
            return null;

        HashSet<Vector3Int> seeds = null;
        for (int i = 0; i < snapshot.VisibleEnemies.Count; i++)
        {
            UnitManager enemy = snapshot.VisibleEnemies[i];
            if (enemy == null || enemy.IsDead)
                continue;

            if (seeds == null)
                seeds = new HashSet<Vector3Int>();

            Vector3Int cell = enemy.CurrentCellPosition;
            cell.z = 0;
            seeds.Add(cell);
        }

        if (seeds == null || seeds.Count == 0)
            return null;

        return ExpandCellsByHexRadius(snapshot.BoardTilemap, seeds, Mathf.Max(0, radius));
    }

    private static HashSet<Vector3Int> ExpandCellsByHexRadius(Tilemap boardTilemap, HashSet<Vector3Int> seeds, int radius)
    {
        if (boardTilemap == null || seeds == null || seeds.Count == 0)
            return null;

        HashSet<Vector3Int> visited = new HashSet<Vector3Int>();
        Queue<Vector3Int> frontier = new Queue<Vector3Int>();
        Queue<int> depths = new Queue<int>();
        foreach (Vector3Int seed in seeds)
        {
            Vector3Int normalized = seed;
            normalized.z = 0;
            if (!visited.Add(normalized))
                continue;

            frontier.Enqueue(normalized);
            depths.Enqueue(0);
        }

        List<Vector3Int> neighbors = new List<Vector3Int>(6);
        while (frontier.Count > 0)
        {
            Vector3Int current = frontier.Dequeue();
            int depth = depths.Dequeue();
            if (depth >= radius)
                continue;

            neighbors.Clear();
            UnitMovementPathRules.GetImmediateHexNeighbors(boardTilemap, current, neighbors);
            for (int i = 0; i < neighbors.Count; i++)
            {
                Vector3Int next = neighbors[i];
                next.z = 0;
                if (!visited.Add(next))
                    continue;

                frontier.Enqueue(next);
                depths.Enqueue(depth + 1);
            }
        }

        return visited;
    }

    private static HashSet<Vector3Int> MergeCellSets(HashSet<Vector3Int> primary, HashSet<Vector3Int> secondary)
    {
        if (primary == null || primary.Count == 0)
            return secondary;
        if (secondary == null || secondary.Count == 0)
            return primary;

        HashSet<Vector3Int> merged = new HashSet<Vector3Int>(primary);
        merged.UnionWith(secondary);
        return merged;
    }

    private bool IsCellTooDangerousForSupport(AISnapshot snapshot, Vector3Int cell, bool allowModerateRiskForSupply = false)
    {
        if (snapshot == null || snapshot.BoardTilemap == null || snapshot.VisibleEnemies == null)
            return false;

        cell.z = 0;
        int nearbyThreats = 0;
        for (int i = 0; i < snapshot.VisibleEnemies.Count; i++)
        {
            UnitManager enemy = snapshot.VisibleEnemies[i];
            if (enemy == null || enemy.IsDead)
                continue;

            Vector3Int enemyCell = enemy.CurrentCellPosition;
            enemyCell.z = 0;
            int dist = GetHexDistance(snapshot.BoardTilemap, cell, enemyCell, 64);
            if (dist == int.MaxValue)
                continue;

            // Bloqueia sempre se inimigo esta adjacente ou a 2 hexes.
            if (dist <= 1)
                return true;
            if (dist <= 2)
                return true;
            if (dist <= 4)
                nearbyThreats++;
        }

        // Em missao de suprimento tolera ate 2 ameacas distantes (dist 3-4); fora disso exige menos de 2.
        return nearbyThreats >= (allowModerateRiskForSupply ? 3 : 2);
    }
    private HashSet<Vector3Int> BuildReservedCaptureCellsForEscort(UnitManager unit, AIPlanIntent unitIntent)
    {
        if (unit == null || unitIntent == null || unitIntent.Assignments == null || unitIntent.Assignments.Count == 0)
            return null;

        HashSet<Vector3Int> reserved = null;
        for (int i = 0; i < unitIntent.Assignments.Count; i++)
        {
            AIPlanAssignment asgn = unitIntent.Assignments[i];
            if (asgn == null || asgn.UnitInstanceId == unit.InstanceId || asgn.Role != AIPlanRole.Capture || !asgn.HasPlannedCaptureTarget)
                continue;

            if (reserved == null)
                reserved = new HashSet<Vector3Int>();

            Vector3Int cell = asgn.PlannedCaptureCell;
            cell.z = 0;
            reserved.Add(cell);
        }

        return reserved;
    }
